4	import type { Route } from "./+types/instructor.$courseId.lessons.$lessonId";
5	import { getCourseById } from "~/services/courseService";
6	import { getLessonById, updateLesson } from "~/services/lessonService";
7	import { getModuleById } from "~/services/moduleService";
8	import { getQuizByLessonId } from "~/services/quizService";
9	import { getCurrentUserId } from "~/lib/session";
10	import { getUserById } from "~/services/userService";
11	import { UserRole } from "~/db/schema";
12	import { Card, CardContent, CardHeader } from "~/components/ui/card";
13	import { Button } from "~/components/ui/button";
14	import { Input } from "~/components/ui/input";
