17	import { AlertTriangle, ArrowLeft, ClipboardList, ExternalLink, Github, Save } from "lucide-react";
18	import { data, isRouteErrorResponse } from "react-router";
19	import { z } from "zod";
20	import { parseFormData, parseParams } from "~/lib/validation";
21	
22	const instructorLessonParamsSchema = z.object({
23	  courseId: z.coerce.number().int(),
24	  lessonId: z.coerce.number().int(),
25	});
26	
27	const updateLessonSchema = z.object({
28	  intent: z.literal("update-lesson"),
29	  content: z.string().optional(),
30	  videoUrl: z.string().trim().optional(),
31	  durationMinutes: z.string().optional(),
32	  githubRepoUrl: z.string().trim().optional(),
33	});
34	
35	export function meta({ data: loaderData }: Route.MetaArgs) {
36	  const title = loaderData?.lesson?.title ?? "Edit Lesson";
37	  return [
38	    { title: `Edit: ${title} — Cadence` },
39	    { name: "description", content: `Edit lesson: ${title}` },
40	  ];
41	}
