150	export default function InstructorLessonEditor({
151	  loaderData,
152	}: Route.ComponentProps) {
153	  const { course, lesson, module: mod, quiz } = loaderData;
154	  const fetcher = useFetcher();
155	
156	  const [content, setContent] = useState(lesson.content ?? "");
157	  const [videoUrl, setVideoUrl] = useState(lesson.videoUrl ?? "");
158	  const [durationMinutes, setDurationMinutes] = useState(
159	    lesson.durationMinutes?.toString() ?? ""
160	  );
161	  const [githubRepoUrl, setGithubRepoUrl] = useState(
162	    lesson.githubRepoUrl ?? ""
163	  );
164	
165	  const hasChanges =
166	    content !== (lesson.content ?? "") ||
167	    videoUrl !== (lesson.videoUrl ?? "") ||
168	    durationMinutes !== (lesson.durationMinutes?.toString() ?? "") ||
169	    githubRepoUrl !== (lesson.githubRepoUrl ?? "");
170	
171	  const blocker = useBlocker(hasChanges);
172	
173	  useEffect(() => {
174	    if (!hasChanges) return;
175	    const handler = (e: BeforeUnloadEvent) => {
176	      e.preventDefault();
177	    };
178	    window.addEventListener("beforeunload", handler);
179	    return () => window.removeEventListener("beforeunload", handler);
180	  }, [hasChanges]);
181	
182	  useEffect(() => {
183	    if (fetcher.state === "idle" && fetcher.data?.success) {
184	      toast.success("Lesson saved.");
185	    }
186	    if (fetcher.state === "idle" && fetcher.data?.error) {
187	      toast.error(fetcher.data.error);
188	    }
189	  }, [fetcher.state, fetcher.data]);
190	
191	  function handleSave() {
192	    fetcher.submit(
193	      {
194	        intent: "update-lesson",
195	        content,
196	        videoUrl,
197	        durationMinutes,
198	        githubRepoUrl,
199	      },
200	      { method: "post" }
201	    );
202	  }
203	
204	  return (
205	    <div className="mx-auto max-w-7xl p-6 lg:p-8">
206	      {/* Unsaved changes blocker dialog */}
207	      {blocker.state === "blocked" && (
208	        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
209	          <Card className="mx-4 w-full max-w-md">
210	            <CardHeader>
211	              <h2 className="text-lg font-semibold">Unsaved Changes</h2>
212	              <p className="text-sm text-muted-foreground">
213	                You have unsaved changes that will be lost if you leave this
214	                page.
215	              </p>
216	            </CardHeader>
217	            <CardContent className="flex justify-end gap-3">
218	              <Button variant="outline" onClick={() => blocker.reset()}>
219	                Stay on Page
220	              </Button>
221	              <Button
222	                variant="destructive"
223	                onClick={() => blocker.proceed()}
224	              >
225	                Leave Page
226	              </Button>
227	            </CardContent>
228	          </Card>
229	        </div>
230	      )}
231	
232	      {/* Breadcrumb */}
233	      <nav className="mb-6 text-sm text-muted-foreground">
234	        <Link to="/instructor" className="hover:text-foreground">
235	          My Courses
236	        </Link>
237	        <span className="mx-2">/</span>
238	        <Link
239	          to={`/instructor/${course.id}`}
240	          className="hover:text-foreground"
241	        >
242	          {course.title}
243	        </Link>
244	        <span className="mx-2">/</span>
245	        <span className="text-foreground">{lesson.title}</span>
246	      </nav>
247	
248	      <Link
249	        to={`/instructor/${course.id}`}
250	        className="mb-4 inline-flex items-center text-sm text-muted-foreground hover:text-foreground"
251	      >
252	        <ArrowLeft className="mr-1 size-4" />
253	        Back to Course Editor
254	      </Link>
255	
256	      <div className="mb-6">
257	        <div className="flex items-center gap-3">
258	          <h1 className="text-3xl font-bold">{lesson.title}</h1>
259	          <Link to={`/courses/${course.slug}/lessons/${lesson.id}`}>
260	            <Button variant="outline" size="sm">
261	              <ExternalLink className="mr-1.5 size-4" />
262	              View Lesson
263	            </Button>
264	          </Link>
265	        </div>
266	        <p className="mt-1 text-sm text-muted-foreground">
267	          Module: {mod.title}
268	        </p>
269	      </div>
270	
271	      <div className="space-y-6">
272	        {/* Content */}
273	        <Card>
274	          <CardHeader>
275	            <h2 className="text-lg font-semibold">Lesson Content</h2>
276	            <p className="text-sm text-muted-foreground">
277	              Write lesson content in Markdown. Press Ctrl+S to format and save.
278	            </p>
279	          </CardHeader>
280	          <CardContent>
281	            <MonacoMarkdownEditor
282	              value={content}
283	              onChange={setContent}
284	              onSave={handleSave}
285	            />
286	          </CardContent>
287	        </Card>
288	
289	        {/* Video URL */}
290	        <Card>
291	          <CardHeader>
292	            <h2 className="text-lg font-semibold">Video</h2>
293	            <p className="text-sm text-muted-foreground">
294	              Paste a YouTube video URL to embed in this lesson.
295	            </p>
296	          </CardHeader>
297	          <CardContent>
298	            <div className="space-y-2">
299	              <Label htmlFor="videoUrl">YouTube URL</Label>
300	              <Input
301	                id="videoUrl"
302	                type="url"
303	                value={videoUrl}
304	                onChange={(e) => setVideoUrl(e.target.value)}
305	                placeholder="https://www.youtube.com/watch?v=..."
306	              />
307	            </div>
308	          </CardContent>
309	        </Card>
310	
311	        {/* Duration */}
312	        <Card>
313	          <CardHeader>
314	            <h2 className="text-lg font-semibold">Duration</h2>
315	            <p className="text-sm text-muted-foreground">
316	              Set the estimated time to complete this lesson.
317	            </p>
318	          </CardHeader>
319	          <CardContent>
320	            <div className="space-y-2">
321	              <Label htmlFor="duration">Duration (minutes)</Label>
322	              <Input
323	                id="duration"
324	                type="number"
325	                min="0"
326	                value={durationMinutes}
327	                onChange={(e) => setDurationMinutes(e.target.value)}
328	                placeholder="e.g. 15"
329	                className="max-w-32"
330	              />
331	            </div>
332	          </CardContent>
333	        </Card>
334	
335	        {/* GitHub Repo */}
336	        <Card>
337	          <CardHeader>
338	            <h2 className="text-lg font-semibold">GitHub Repository</h2>
339	            <p className="text-sm text-muted-foreground">
340	              Link to a GitHub repository for this lesson's code.
341	            </p>
342	          </CardHeader>
343	          <CardContent>
344	            <div className="space-y-2">
345	              <Label htmlFor="githubRepoUrl">Repository URL</Label>
346	              <Input
347	                id="githubRepoUrl"
348	                type="url"
349	                value={githubRepoUrl}
350	                onChange={(e) => setGithubRepoUrl(e.target.value)}
351	                placeholder="https://github.com/owner/repo"
352	              />
353	            </div>
354	          </CardContent>
355	        </Card>
356	
357	        {/* Quiz */}
358	        <Card>
359	          <CardHeader>
360	            <h2 className="text-lg font-semibold">Quiz</h2>
361	            <p className="text-sm text-muted-foreground">
362	              {quiz
363	                ? `This lesson has a quiz: "${quiz.title}"`
364	                : "No quiz attached to this lesson yet."}
365	            </p>
366	          </CardHeader>
367	          <CardContent>
368	            <Link
369	              to={`/instructor/${course.id}/lessons/${lesson.id}/quiz`}
370	            >
371	              <Button variant="outline">
372	                <ClipboardList className="mr-1.5 size-4" />
373	                {quiz ? "Edit Quiz" : "Create Quiz"}
374	              </Button>
375	            </Link>
376	          </CardContent>
377	        </Card>
378	
379	        {/* Save Button */}
380	        <div className="flex items-center gap-4">
381	          <Button
382	            onClick={handleSave}
383	            disabled={!hasChanges || fetcher.state !== "idle"}
384	          >
385	            <Save className="mr-1.5 size-4" />
386	            {fetcher.state !== "idle" ? "Saving..." : "Save Changes"}
387	          </Button>
388	          {hasChanges && (
389	            <span className="text-sm text-muted-foreground">
390	              You have unsaved changes.
391	            </span>
392	          )}
393	        </div>
394	      </div>
395	    </div>
396	  );
397	}
