5	// ─── Lesson Service ───
6	// Handles lesson CRUD and reordering within modules.
7	// Uses positional parameters (project convention).
8	
9	export function getLessonById(id: number) {
10	  return db.select().from(lessons).where(eq(lessons.id, id)).get();
11	}
12	
13	export function getLessonsByModule(moduleId: number) {
14	  return db
15	    .select()
16	    .from(lessons)
17	    .where(eq(lessons.moduleId, moduleId))
18	    .orderBy(lessons.position)
19	    .all();
20	}
21	
22	export function getLessonCount(moduleId: number) {
23	  const result = db
24	    .select({ count: sql<number>`count(*)` })
25	    .from(lessons)
26	    .where(eq(lessons.moduleId, moduleId))
27	    .get();
28	  return result?.count ?? 0;
29	}
30	
31	export function createLesson(
32	  moduleId: number,
33	  title: string,
34	  content: string | null,
35	  videoUrl: string | null,
36	  position: number | null,
37	  durationMinutes: number | null
38	) {
39	  const pos =
40	    position ??
41	    db
42	      .select({ max: sql<number>`coalesce(max(${lessons.position}), 0)` })
43	      .from(lessons)
44	      .where(eq(lessons.moduleId, moduleId))
45	      .get()!.max + 1;
46	
47	  return db
48	    .insert(lessons)
49	    .values({
50	      moduleId,
51	      title,
52	      content,
53	      videoUrl,
54	      position: pos,
55	      durationMinutes,
56	    })
57	    .returning()
58	    .get();
59	}
60	
61	export function updateLesson(
62	  id: number,
63	  title: string | null,
64	  content: string | null,
65	  videoUrl: string | null,
66	  durationMinutes: number | null,
67	  githubRepoUrl: string | null = null
68	) {
69	  const updates: Record<string, unknown> = {};
70	  if (title !== null) updates.title = title;
