112	export function moveLessonToPosition(lessonId: number, newPosition: number) {
113	  const lesson = getLessonById(lessonId);
114	  if (!lesson) return null;
115	
116	  const oldPosition = lesson.position;
117	  if (oldPosition === newPosition) return lesson;
118	
119	  if (newPosition > oldPosition) {
120	    // Moving down: shift items between old+1 and new up by 1
121	    db.update(lessons)
122	      .set({ position: sql`${lessons.position} - 1` })
123	      .where(
124	        and(
125	          eq(lessons.moduleId, lesson.moduleId),
126	          gt(lessons.position, oldPosition),
127	          lte(lessons.position, newPosition)
128	        )
129	      )
130	      .run();
131	  } else {
132	    // Moving up: shift items between new and old-1 down by 1
133	    db.update(lessons)
134	      .set({ position: sql`${lessons.position} + 1` })
135	      .where(
136	        and(
137	          eq(lessons.moduleId, lesson.moduleId),
138	          gte(lessons.position, newPosition),
139	          lt(lessons.position, oldPosition)
140	        )
141	      )
142	      .run();
143	  }
144	
145	  return db
146	    .update(lessons)
147	    .set({ position: newPosition })
148	    .where(eq(lessons.id, lessonId))
149	    .returning()
150	    .get();
151	}
