153	export function swapLessonPositions(lessonIdA: number, lessonIdB: number) {
154	  const lessonA = getLessonById(lessonIdA);
155	  const lessonB = getLessonById(lessonIdB);
156	  if (!lessonA || !lessonB) return null;
157	
158	  db.update(lessons)
159	    .set({ position: lessonB.position })
160	    .where(eq(lessons.id, lessonIdA))
161	    .run();
162	
163	  db.update(lessons)
164	    .set({ position: lessonA.position })
165	    .where(eq(lessons.id, lessonIdB))
166	    .run();
167	
168	  return {
169	    a: { ...lessonA, position: lessonB.position },
170	    b: { ...lessonB, position: lessonA.position },
171	  };
172	}
