184	/**
185	 * Move a lesson from one module to another at a specific position.
186	 * Closes the gap in the source module and opens a gap in the destination module.
187	 */
188	export function moveLessonToModule(
189	  lessonId: number,
190	  targetModuleId: number,
191	  targetPosition: number
192	) {
193	  const lesson = getLessonById(lessonId);
194	  if (!lesson) return null;
195	
196	  const sourceModuleId = lesson.moduleId;
197	
198	  // 1. Close the gap in the source module
199	  db.update(lessons)
200	    .set({ position: sql`${lessons.position} - 1` })
201	    .where(
202	      and(
203	        eq(lessons.moduleId, sourceModuleId),
204	        gt(lessons.position, lesson.position)
205	      )
206	    )
207	    .run();
208	
209	  // 2. Open a gap in the destination module
210	  db.update(lessons)
211	    .set({ position: sql`${lessons.position} + 1` })
212	    .where(
213	      and(
214	        eq(lessons.moduleId, targetModuleId),
215	        gte(lessons.position, targetPosition)
216	      )
217	    )
218	    .run();
219	
220	  // 3. Move the lesson to the target module at the target position
221	  return db
222	    .update(lessons)
223	    .set({ moduleId: targetModuleId, position: targetPosition })
224	    .where(eq(lessons.id, lessonId))
225	    .returning()
226	    .get();
227	}
