52	export function buildCourseQuery(
53	  search: string | null,
54	  category: string | null,
55	  status: CourseStatus | null,
56	  sortBy: string | null,
57	  limit: number,
58	  offset: number
59	) {
60	  const conditions = [];
61	
62	  if (status) {
63	    conditions.push(eq(courses.status, status));
64	  }
65	
66	  if (search) {
67	    const term = `%${search}%`;
68	    conditions.push(
69	      or(like(courses.title, term), like(courses.description, term))!
70	    );
71	  }
72	
73	  const query = db
74	    .select({
75	      id: courses.id,
76	      title: courses.title,
77	      slug: courses.slug,
78	      description: courses.description,
79	      salesCopy: courses.salesCopy,
80	      instructorId: courses.instructorId,
81	      categoryId: courses.categoryId,
82	      status: courses.status,
83	      coverImageUrl: courses.coverImageUrl,
84	      price: courses.price,
85	      pppEnabled: courses.pppEnabled,
86	      createdAt: courses.createdAt,
87	      updatedAt: courses.updatedAt,
88	      instructorName: users.name,
89	      instructorAvatarUrl: users.avatarUrl,
90	      categoryName: categories.name,
91	    })
92	    .from(courses)
93	    .innerJoin(users, eq(courses.instructorId, users.id))
94	    .innerJoin(categories, eq(courses.categoryId, categories.id));
95	
96	  if (category) {
97	    conditions.push(eq(categories.slug, category));
98	  }
99	
100	  const filtered =
101	    conditions.length > 0 ? query.where(and(...conditions)) : query;
102	
103	  const sorted =
104	    sortBy === "title"
105	      ? filtered.orderBy(courses.title)
106	      : sortBy === "oldest"
107	        ? filtered.orderBy(courses.createdAt)
108	        : filtered.orderBy(sql`${courses.createdAt} DESC`);
109	
110	  return sorted.limit(limit).offset(offset).all();
111	}
