82	export function moveModuleToPosition(moduleId: number, newPosition: number) {
83	  const mod = getModuleById(moduleId);
84	  if (!mod) return null;
85	
86	  const oldPosition = mod.position;
87	  if (oldPosition === newPosition) return mod;
88	
89	  if (newPosition > oldPosition) {
90	    // Moving down: shift items between old+1 and new up by 1
91	    db.update(modules)
92	      .set({ position: sql`${modules.position} - 1` })
93	      .where(
94	        and(
95	          eq(modules.courseId, mod.courseId),
96	          gt(modules.position, oldPosition),
97	          lte(modules.position, newPosition)
98	        )
99	      )
100	      .run();
101	  } else {
102	    // Moving up: shift items between new and old-1 down by 1
103	    db.update(modules)
104	      .set({ position: sql`${modules.position} + 1` })
105	      .where(
106	        and(
107	          eq(modules.courseId, mod.courseId),
108	          gte(modules.position, newPosition),
109	          lt(modules.position, oldPosition)
110	        )
111	      )
112	      .run();
113	  }
114	
115	  return db
116	    .update(modules)
117	    .set({ position: newPosition })
118	    .where(eq(modules.id, moduleId))
119	    .returning()
120	    .get();
121	}
