123	export function swapModulePositions(moduleIdA: number, moduleIdB: number) {
124	  const modA = getModuleById(moduleIdA);
125	  const modB = getModuleById(moduleIdB);
126	  if (!modA || !modB) return null;
127	
128	  db.update(modules)
129	    .set({ position: modB.position })
130	    .where(eq(modules.id, moduleIdA))
131	    .run();
132	
133	  db.update(modules)
134	    .set({ position: modA.position })
135	    .where(eq(modules.id, moduleIdB))
136	    .run();
137	
138	  return {
139	    a: { ...modA, position: modB.position },
140	    b: { ...modB, position: modA.position },
141	  };
142	}
