144	export function reorderModules(courseId: number, moduleIds: number[]) {
145	  for (let i = 0; i < moduleIds.length; i++) {
146	    db.update(modules)
147	      .set({ position: i + 1 })
148	      .where(and(eq(modules.id, moduleIds[i]), eq(modules.courseId, courseId)))
149	      .run();
150	  }
151	  return getModulesByCourse(courseId);
152	}
