54	/**
55	 * Parses a JSON request body with a Zod schema.
56	 * Returns either the parsed data or a field-error map (first error per field).
57	 */
58	export async function parseJsonBody<T extends z.ZodType>(
59	  request: Request,
60	  schema: T
61	): Promise<ParseResult<z.infer<T>>> {
62	  const raw = await request.json();
63	  const result = schema.safeParse(raw);
64	
65	  if (result.success) {
66	    return { success: true, data: result.data };
67	  }
68	
69	  const fieldErrors = result.error.flatten().fieldErrors;
70	  const errors: Record<string, string> = {};
71	  for (const [key, messages] of Object.entries(fieldErrors)) {
72	    if (messages && messages.length > 0) {
73	      errors[key] = messages[0];
74	    }
75	  }
76	
77	  return { success: false, errors };
