### 4. ACTION/LOADER STRUCTURE PATTERNS

**Example 1: Student Lesson View Route**
**File:** `/home/saaln/cohort-003-project/app/routes/courses.$slug.lessons.$lessonId.tsx`

**Loader (lines 102-219):**
```typescript
export async function loader({ params, request }: Route.LoaderArgs) {
  const slug = params.slug;
  const lessonId = Number(params.lessonId);

  // Validation
  if (isNaN(lessonId)) throw data("Invalid lesson ID", { status: 400 });

  // Fetch with relationship validation
  const course = getCourseBySlug(slug);
  const courseWithDetails = getCourseWithDetails(course.id);
  const lesson = getLessonById(lessonId);
  const mod = getModuleById(lesson.moduleId);

  // Verify lesson belongs to course
  if (mod.courseId !== course.id) {
    throw data("Lesson not found in this course", { status: 404 });
  }

  // Conditional data loading (only if user enrolled)
  const currentUserId = await getCurrentUserId(request);
  if (currentUserId) {
    enrolled = isUserEnrolled(currentUserId, course.id);
    if (enrolled) {
      markLessonInProgress(currentUserId, lessonId);
      lessonStatus = getLessonProgress(currentUserId, lessonId)?.status;
      // More data loading...
    }
  }

  // PPP access guard
  const pppBlocked = checkPppAccess(...).blocked;

  // Server-side markdown rendering
  const contentHtml = lesson.content ? await renderMarkdown(lesson.content) : null;

  // Build navigation
  const allLessons = flattenCourseLessons(courseWithDetails);
  const currentIndex = allLessons.findIndex(l => l.id === lessonId);
  const prevLesson = currentIndex > 0 ? allLessons[currentIndex - 1] : null;
  const nextLesson = currentIndex < allLessons.length - 1 ? allLessons[currentIndex + 1] : null;
}
```

